function jumiProps_(){return PropertiesService.getScriptProperties();}
function jumiAssert_(condition,message){if(!condition)throw new Error(message);}
function jumiSafe_(value){const text=String(value==null?'':value).trim();return /^[=+\-@]/.test(text)?"'"+text:text;}
function jumiEmail_(value){return String(value||'').trim().toLowerCase();}
function jumiDateText_(value,pattern){return value instanceof Date?Utilities.formatDate(value,JUMI_TZ,pattern):String(value||'').trim();}
function jumiStamp_(dateValue,timeValue){return[jumiDateText_(dateValue,'yyyy-MM-dd'),jumiDateText_(timeValue,'HH:mm:ss')].filter(Boolean).join(' ');}
function jumiId_(prefix){return prefix+'_'+Utilities.getUuid().replace(/-/g,'');}
function jumiNow_(){return Utilities.formatDate(new Date(),JUMI_TZ,"yyyy-MM-dd'T'HH:mm:ssXXX");}
function jumiJson_(value,fallback){try{return JSON.parse(String(value||''));}catch(_){return fallback;}}
function jumiHex_(bytes){return bytes.map(value=>('0'+((value+256)%256).toString(16)).slice(-2)).join('');}
function jumiSha256_(blob){return jumiHex_(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,blob.getBytes()));}
