function jumiOptionalTab_(ss,key){const spec=JUMI_TABS[key],id=jumiProps_().getProperty('JUMI_TAB_'+key.toUpperCase()),mapped=id?ss.getSheetById(Number(id)):null;return mapped&&mapped.getName()===spec[0]?mapped:ss.getSheetByName(spec[0]);}
function jumiHeaders_(sheet,headers){jumiAssert_(sheet.getLastRow()>=1,'Missing '+sheet.getName()+' headers.');const width=sheet.getLastColumn(),existing=sheet.getRange(1,1,1,width).getValues()[0].map(String),prefix=headers.slice(0,existing.length);jumiAssert_(existing.length<=headers.length&&JSON.stringify(existing)===JSON.stringify(prefix),'Unexpected '+sheet.getName()+' headers.');if(sheet.getMaxColumns()<headers.length)sheet.insertColumnsAfter(sheet.getMaxColumns(),headers.length-sheet.getMaxColumns());if(existing.length<headers.length)sheet.getRange(1,existing.length+1,1,headers.length-existing.length).setValues([headers.slice(existing.length)]);}
function jumiObjects_(sheet,headers){if(sheet.getLastRow()<2)return[];return sheet.getRange(2,1,sheet.getLastRow()-1,headers.length).getValues().map((row,index)=>Object.fromEntries(headers.map((header,column)=>[header,row[column]]))).map((item,index)=>({...item,_row:index+2}));}
