function setupJumiContentStorage(){
  const props=jumiProps_(),owner=jumiEmail_(Session.getEffectiveUser().getEmail()),allowlist=jumiJson_(props.getProperty('JUMI_ADMIN_ALLOWLIST'),[]).map(jumiEmail_);jumiAssert_(owner&&allowlist.includes(owner),'Run content storage setup as an authorized owner.');
  let root,id=props.getProperty('JUMI_CONTENT_ROOT_FOLDER_ID');
  if(id)root=DriveApp.getFolderById(id);else{const matches=DriveApp.getFoldersByName('JUMI Content Sources');jumiAssert_(!matches.hasNext(),'A folder named JUMI Content Sources already exists. Set its ID explicitly after verifying ownership and Restricted access.');root=DriveApp.createFolder('JUMI Content Sources');props.setProperty('JUMI_CONTENT_ROOT_FOLDER_ID',root.getId());}
  jumiAssert_(root.getSharingAccess()===DriveApp.Access.PRIVATE,'Content Sources folder must remain private.');['Articles','eBooks','Seminars','Certificates'].forEach(name=>jumiChildFolder_(root,name));return{configured:true,folder:'JUMI Content Sources'};
}

function setupJumi(){
  const props=jumiProps_(),trackerId=props.getProperty('JUMI_TRACKER_ID'),owner=jumiEmail_(Session.getEffectiveUser().getEmail());
  jumiAssert_(trackerId,'Set JUMI_TRACKER_ID in Script Properties first.');
  const ss=SpreadsheetApp.openById(trackerId);
  jumiAssert_(ss&&owner,'Run setup as the tracker owner.');
  const admins=jumiJson_(props.getProperty('JUMI_ADMIN_ALLOWLIST'),[]);
  jumiAssert_(Array.isArray(admins)&&admins.length&&admins.every(email=>jumiEmail_(email)===email),'Set JUMI_ADMIN_ALLOWLIST to a JSON array of normalized admin emails.');
  const lock=LockService.getScriptLock();lock.waitLock(10000);
  try{
    props.setProperty('JUMI_OWNER',owner);ss.setSpreadsheetTimeZone(JUMI_TZ);
    Object.keys(JUMI_TABS).forEach(key=>{const [name,headers]=JUMI_TABS[key];let sheet=ss.getSheetByName(name);sheet=sheet||ss.insertSheet(name);if(!sheet.getLastRow())sheet.getRange(1,1,1,headers.length).setValues([headers]);jumiHeaders_(sheet,headers);sheet.setFrozenRows(1);sheet.getRange(1,1,1,headers.length).setFontWeight('bold').setBackground('#981d36').setFontColor('#fff').setWrap(true);props.setProperty('JUMI_TAB_'+key.toUpperCase(),String(sheet.getSheetId()));});
    const events=jumiTab_(ss,'events'),existing=jumiObjects_(events,JUMI_EVENT_HEADERS);
    if(!existing.some(row=>row['Event ID']==='management-thyroid-nodules-2026'))jumiWriteRow_(events,JUMI_EVENT_HEADERS,{'Event ID':'management-thyroid-nodules-2026','Title':'Management of Thyroid Nodules — How to Make a Good Diagnosis?','Subtitle':'','Start At':'2026-09-19T09:00:00+07:00','End At':'2026-09-19T11:00:00+07:00','Registration Open':'','Registration Close':'','Format':'Online','Platform':'Zoom','Meeting URL':'','Venue':'','Address':'','Commercial':'Free','Price':'','Currency':'IDR','Payment Instructions Ref':'','Poster Ref':'assets/events/management-thyroid-nodules-2026-official-poster.jpeg','Speakers JSON':'[]','Description':'Imported from the approved BA Medicale event record. Missing private operational fields remain pending.','Audience':'Doctors','Capacity':'1000','SKP Info':'Available in the approved event source','LMS Info':'Available in the approved event source','Lifecycle':'Completed','Public URL':'https://bamedicale.com/events/management-thyroid-nodules-2026.html','Updated At':jumiNow_(),'Updated By':owner});
    jumiAssert_(props.getProperty('JUMI_PAYMENT_ROOT_FOLDER_ID'),'Set JUMI_PAYMENT_ROOT_FOLDER_ID to the existing private Payment Validation folder first.');
    const paymentRoot=DriveApp.getFolderById(props.getProperty('JUMI_PAYMENT_ROOT_FOLDER_ID'));jumiAssert_(paymentRoot.getSharingAccess()===DriveApp.Access.PRIVATE,'Payment Validation folder must remain private.');
    jumiAssert_(props.getProperty('JUMI_CONTENT_ROOT_FOLDER_ID'),'Set JUMI_CONTENT_ROOT_FOLDER_ID to the private Content Sources folder first.');
    const contentRoot=DriveApp.getFolderById(props.getProperty('JUMI_CONTENT_ROOT_FOLDER_ID'));jumiAssert_(contentRoot.getSharingAccess()===DriveApp.Access.PRIVATE,'Content Sources folder must remain private.');['Articles','eBooks','Seminars','Certificates'].forEach(name=>jumiChildFolder_(contentRoot,name));
    jumiAssert_(jumiGithubConfigured_(),'Set JUMI_GITHUB_TOKEN in Script Properties first.');const repository=jumiGithub_('get','',undefined,[200]);jumiAssert_(repository.full_name===JUMI_GITHUB_OWNER+'/'+JUMI_GITHUB_REPO,'Publisher credential is not restricted to the configured BA Medicale repository.');jumiGithub_('get','/pages',undefined,[200]);
    SpreadsheetApp.flush();
  }finally{lock.releaseLock();}
}

function setupJumiNotifications(){
  const admin=jumiAuthorize_(),props=jumiProps_();
  jumiAssert_(jumiEmailProviderConfigured_(),'Set JUMI_RESEND_API_KEY and confirm JUMI_EMAIL_SENDER_VERIFIED=true only after bamedicale.com is verified in Resend.');
  ScriptApp.getProjectTriggers().filter(trigger=>trigger.getHandlerFunction()==='processJumiNotificationQueue').forEach(trigger=>ScriptApp.deleteTrigger(trigger));
  ScriptApp.newTrigger('processJumiNotificationQueue').timeBased().everyMinutes(15).create();
  props.setProperty('JUMI_NOTIFICATION_TRIGGER_OWNER',admin.email);
  return{configured:true,provider:JUMI_EMAIL_PROVIDER,sender:JUMI_EMAIL_FROM,schedule:'Every 15 minutes'};
}

function processJumiNotificationQueue(){
  const props=jumiProps_(),effective=jumiEmail_(Session.getEffectiveUser().getEmail()),owner=jumiEmail_(props.getProperty('JUMI_OWNER')),allowlist=jumiJson_(props.getProperty('JUMI_ADMIN_ALLOWLIST'),[]).map(jumiEmail_);
  jumiAssert_(effective&&effective===owner&&allowlist.includes(effective),'Notification trigger owner is not authorized.');
  return jumiProcessNotificationQueue_({email:effective,role:'Owner'});
}

function jumiAuthorize_(){
  const email=jumiEmail_(Session.getActiveUser().getEmail()),allowlist=jumiJson_(jumiProps_().getProperty('JUMI_ADMIN_ALLOWLIST'),[]).map(jumiEmail_);
  jumiAssert_(email&&allowlist.includes(email),'Access denied.');
  return{email,role:email===jumiEmail_(jumiProps_().getProperty('JUMI_OWNER'))?'Owner':'Admin'};
}
