  const lock=LockService.getScriptLock();lock.waitLock(10000);try{jumiUpdateRow_(sheet,row._row,JUMI_REGISTRANT_HEADERS,next);jumiAudit_(ss,admin,'MARK_PAID','registrant',row['Registrant ID'],row,next);SpreadsheetApp.flush();}finally{lock.releaseLock();}jumiSyncNotifications_(ss,admin,{eventId:String(row['Event ID'])});return{saved:true,confirmationQueued:true};
