    if(!speaker)event.speakerRecords.push({id,name,credentials:'',role:'Speaker',topic:item.title,catalogOnly:true});
    if(!event.presentations.some(row=>row.id===item.id||row.typeData?.publication?.speakerId===id))event.presentations.push({id:item.id,type:'Presentation',title:item.title,status:'Published',publicUrl:item.publicUrl,catalogOnly:true,typeData:{publication:{eventId:event.id,speakerId:id}}});
